{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Phase 1 - Foundation",
      "weeks": 4,
      "focus": "Stability, light load comprehension, and movement re-education with emphasis on knee-friendly mechanics."
    },
    {
      "name": "Phase 2 - Build & Control",
      "weeks": 4,
      "focus": "Progressive loading with controlled tempo to build strength while protecting the knee."
    },
    {
      "name": "Phase 3 - Strength Transfer",
      "weeks": 4,
      "focus": "Increase absolute load and introduce ski-specific patterns within safe ranges."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Upper",
      "Lower (safe)",
      "Push/Pull",
      "Accessory / Mobility"
    ]
  },
  "non_negotiables": [
    "No jumping",
    "No deep knee flexion under load",
    "Surgeon clearance required; all exercises must be knee-friendly and pain-free",
    "Full gym access with barbells, dumbbells, machines; avoid impact-based movements",
    "Progression must use submaximal loads with attention to form and pain signals",
    "Warm-up included prior to each session with knee-friendly mobility and activation",
    "Return-to-sport plan aligned with skiing goals and not to exceed pain-free ROM"
  ]
}
